$job = Start-Process pwsh -ArgumentList '-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', 'C:\LocalAI_Workstation\LexMind_一鍵正式啟動.ps1' -PassThru -WindowStyle Hidden; Start-Sleep -Seconds 15; if (-not $job.HasExited) { Stop-Process -Id $job.Id -Force; Write-Output 'SUCCESS: Script ran for 15s without crashing.' } else { Write-Output "FAILED: Script crashed with exit code $($job.ExitCode)" }
